methods.body:
if (this.disabled || e.repeat) return
if (e.key == "Enter" || e.key == " ") this.press()
else if (e.key == "ArrowDown" && this.menu != null) this.openMenu()

const ss = this.segs()
const i = ss.indexOf(seg)
if (i < 0) return
// past either end it wraps, as a radio group and a tab list do
const n = (i + d + ss.length) % ss.length
if (n == i) return
const to = ss[n]
Focus.focus(to)
// choices that are places switch on the arrow, as a tab bar does
if (to.link != "") (this.root).follow(to.link, to.replace)

const s = parent
d.fillStyle = (this.$provided("theme").segmentDividerColor ?? this.$provided("theme").line)
for (let i = 1; i < s.count; i++) {
    const near = s.idx < 0 ? 1 : Math.abs(s.lane + 0.5 - i)
    const a = Math.max(0, Math.min(1, (near - 0.5) * 2))
    if (a <= 0) continue
    d.globalAlpha = a
    d.fillRect(2 + i * s.segW - 0.5, 7, 1, this.height - 14)
    }

if (this.disabled) return
if (e.key == "Enter" || e.key == " ") this.press()
else if (e.key == "ArrowRight" || e.key == "ArrowDown") (this.parent).roveFrom(this, 1)
else if (e.key == "ArrowLeft" || e.key == "ArrowUp") (this.parent).roveFrom(this, -1)

d.scale(this.unit, this.unit)
d.fillStyle = this.ink
d.strokeStyle = this.ink
d.lineWidth = this.weight / this.unit
d.lineCap = "round"
// The ring is drawn a touch smaller than the solid disc: a stroke straddles
// its path, so an outline at the filled radius reads as the larger mark.
d.beginPath()
d.arc(8, 8, classroot.solid ? 3.5 : 3.15, 0, Math.PI * 2, false)
if (classroot.solid) d.fill()
else d.stroke()
for (let i = 0; i < classroot.rays; i++) {
    const a = (i / classroot.rays) * Math.PI * 2
    const c = Math.cos(a), s = Math.sin(a)
    d.beginPath()
    d.moveTo(8 + c * 5.3, 8 + s * 5.3)
    d.lineTo(8 + c * 6.9, 8 + s * 6.9)
    d.stroke()
    }

if (classroot.paintsIn != null) return
let top = null
let pinned = false
for (let n = v; n != null && n != this.root; n = (n.paintsIn != null ? n.paintsIn : n.parent)) {
    if (n.ignoreScroll) pinned = true
    top = n
    }
let chrome = null
if (!pinned && !this.overlayUp && top != null) {
    let after = false
    for (const k of this.root.childViews) {
        if (k == top) { after = true; continue }
        if (after && k != classroot && k.ignoreScroll && k.visible && k.pointerEvents != "none" && k.height < this.root.height / 2) { chrome = k; break }
        }
    }
classroot.raise(chrome)

const Q = Math.PI / 2
const dist = Math.abs(this.x - this.tx) + Math.abs(this.y - this.ty) + Math.abs(this.width - this.tw) + Math.abs(this.height - this.th)
const lw = this.$provided("theme").focusRingWidth
// The arrival overshoot stays inside the scroller the ring rides: the
// outline is held to the scroller's visible frame (or the target, where
// the target itself runs past it), so a bounce at a pane's edge flattens
// against the edge rather than being cut off by it.
let L = 0, T = 0, R = this.width, B = this.height
if (Math.abs(this.rotation) < 0.01) {
    const sc = (classroot.paintsIn != null ? classroot.paintsIn : this.root)
    const m = lw / 2
    L = Math.max(0, Math.min(sc.scrollX + m, this.tx) - this.x)
    T = Math.max(0, Math.min(sc.scrollY + m, this.ty) - this.y)
    R = Math.min(this.width, Math.max(sc.scrollX + sc.width - m, this.tx + this.tw) - this.x)
    B = Math.min(this.height, Math.max(sc.scrollY + sc.height - m, this.ty + this.th) - this.y)
    if (R - L < 1 || B - T < 1) return
    }
const w = R - L, h = B - T
const small = Math.min(w, h) < 40
// By default the ring travels as a closed outline, source shape to
// destination shape — no bracket mode intervening. `provided("theme").focusSights
// = true` elects the sights rendition instead (data, not a code path):
// fully open in motion, arms sweeping shut inside the last 16px of
// settle.
const cov = this.$provided("theme").focusSights == true && !small ? Math.max(0.22, 1 - dist / 16) : 1
// The indicator is one band or two, by data: `focusRingInnerWidth` > 0
// adds an inner stroke between the control and the outer one — the
// Redmond two-tone focus rectangle, black over white. Both passes are
// the same outline at different insets; the flight, the sights, and
// the silhouette machinery are shared, not forked.
const iw = this.$provided("theme").focusRingInnerWidth
const pass = (ins, lwp, color) => {
    const r = Math.max(1, Math.min(this.rad - ins, Math.min(w, h) / 2 - ins))
    const ax = Math.max(0, ((w - 2 * ins) / 2 - r) * cov)      // horizontal arm length
    const ay = Math.max(0, ((h - 2 * ins) / 2 - r) * cov)      // vertical arm length
    d.strokeStyle = color
    d.lineWidth = lwp
    d.beginPath()
    // each corner: arc + arms, inset symmetrically
    const x0 = L + ins, y0 = T + ins, x1 = R - ins, y1 = B - ins
    d.moveTo(x0 + r + ax, y0); d.lineTo(x0 + r, y0); d.arc(x0 + r, y0 + r, r, -Q, Math.PI, true); d.lineTo(x0, y0 + r + ay)
    d.moveTo(x1 - r - ax, y0); d.lineTo(x1 - r, y0); d.arc(x1 - r, y0 + r, r, -Q, 0); d.lineTo(x1, y0 + r + ay)
    d.moveTo(x1, y1 - r - ay); d.lineTo(x1, y1 - r); d.arc(x1 - r, y1 - r, r, 0, Q); d.lineTo(x1 - r - ax, y1)
    d.moveTo(x0 + r + ax, y1); d.lineTo(x0 + r, y1); d.arc(x0 + r, y1 - r, r, Q, Math.PI); d.lineTo(x0, y1 - r - ay)
    d.stroke()
    }
pass(0, lw, (this.$provided("theme").focusRingColor ?? this.$provided("theme").accent))
if (iw > 0) pass((lw + iw) / 2, iw, (this.$provided("theme").focusRingInnerColor ?? this.$provided("theme").surface))

if (g.root != this.root) return
// Ride the target's scroller: the ring paints in it (paintsIn) and
// positions in its content coordinates — the platform then carries
// ring and control together, zero lag, no per-scroll re-derive
// (planes.md §14).
const prev = (this)._lastTarget
const prevHome = (this)._lastHome
const hadHome = (this)._hasHome === true
const px = classroot.x
const py = classroot.y
classroot.paintsIn = g.scroller == this.root ? null : g.scroller
const homed = g.scroller != this.root
// the home box: the scroller's content space, the page's when it
// rides none — and turned, when the control is (a tilted window)
const gx = g.homeX
const gy = g.homeY
// Crossing scroll homes (the bar's button → a control in the
// scrolled page): the flight must still fly. The ring's current
// position converts through root space into the destination
// home's coordinates — same painted spot, new numbers — and the
// springs then travel entirely within the new space (correct
// even if that pane scrolls mid-flight).
if (hadHome && prevHome != g.scroller) {
    const toRoot = prevHome == null || prevHome == this.root
        ? ({ x: px, y: py })
        : (() => { const o = prevHome.rootOrigin(); return ({ x: o.x + px - prevHome.scrollX, y: o.y + py - prevHome.scrollY }) })()
    const dst = !homed || g.scroller == this.root
        ? toRoot
        : (() => { const o = g.scroller.rootOrigin(); return ({ x: toRoot.x - o.x + g.scroller.scrollX, y: toRoot.y - o.y + g.scroller.scrollY }) })()
    classroot.x = dst.x
    classroot.y = dst.y
    }
const gap = this.$provided("theme").focusRingGap
const lw = this.$provided("theme").focusRingWidth
const iw = this.$provided("theme").focusRingInnerWidth
// where the scroller it rides would cut the ring off — across its
// scroll direction, where no scroll ever brings the edge in — the
// ring is drawn inside the control instead (planes.md §14)
const outside = gap + iw + lw / 2
const sc = homed && g.scroller != this.root ? g.scroller : null
const gw = g.homeW
const gh = g.homeH
const turned = g.homeRot != 0
const cutY = !turned && sc != null && sc.scrolls != "y" && (gy - outside < 0 || gy + gh + outside > sc.height)
const cutX = !turned && sc != null && sc.scrolls != "x" && (gx - outside < 0 || gx + gw + outside > sc.width)
const off = cutX || cutY ? -(lw / 2 + 1) : outside
// a traveled ring draws the content-space box (homeW/homeH/homeRad):
// any ancestor transform above the scroller reaches its surface
// through the platform, so frame-space extents would double-apply it
// the band's outset runs along the control's own axes, so a turned
// ring's origin steps back along them (it turns about that origin)
const ca = Math.cos(g.homeRot * Math.PI / 180), sa = Math.sin(g.homeRot * Math.PI / 180)
const nx = gx - off * ca + off * sa, ny = gy - off * sa - off * ca
const moved = Math.abs(nx - classroot.tx) + Math.abs(ny - classroot.ty) + Math.abs(gw + 2 * off - classroot.tw) + Math.abs(gh + 2 * off - classroot.th) > 0.5
classroot.tx = nx; classroot.ty = ny
classroot.tw = gw + 2 * off; classroot.th = gh + 2 * off
classroot.trad = g.homeRad + off
classroot.trot = g.homeRot
// Only a focus change flies. The same control moving under a resting
// ring — a dragged slider thumb, a reflow — takes the ring with it
// rigidly: the springs' targets just moved, so land them now. The
// discriminator is target identity (a handler-scratch expando — not
// reactive state, just the previous event's view for comparison),
// and a real move: the same geometry delivered again (the follower
// re-runs as the focus change settles) must not cut the flight short.
;(this)._lastTarget = g.view
;(this)._lastHome = g.scroller
;(this)._hasHome = true
if (classroot.shown) classroot.restack(g.view)
if (prev == g.view && moved) classroot.snapTo()

classroot.noteOverlayFocus()
if (v == null) { classroot.shown = false; return }
let n = v
for (; n != null && n.parent != null; n = n.parent) { }
// Another app on the page (an embedded preview) owns this target — its own
// ring indicates it; this one stands down rather than chase foreign coordinates.
if (n != this.root) { classroot.shown = false; return }
// Pointer focus: park silently — geometry current, ring hidden. The next
// keyboard flight departs from here (the just-clicked control).
if (!Focus.byKeyboard()) { classroot.shown = false; classroot.snapTo(); classroot.placed = true; return }
if (classroot.ringRole() == "off") { classroot.shown = false; return }
// No flight when: the ring has never been placed, the theme suppressed
// the flourish, or the role is rest-only (appear in place, stay).
if (!classroot.placed || this.$provided("theme").focusAnimate == false || !classroot.travelRole()) classroot.snapTo()
classroot.placed = true
classroot.shown = true
classroot.restack(v)  // chrome stays chrome: above whatever raised last (a Dialog, a Menu), under the page's pinned bars
// idle fade only for the travel-only role — a resting ring persists
if (classroot.restRole()) { classroot.idle = false; return }
classroot.gen = classroot.gen + 1
const g2 = classroot.gen
classroot.idle = false
this.$afterDelay(1000, () => { if (classroot.gen == g2) classroot.idle = true })

if (v == null) return ({ x: 0, y: 0, w: 0, h: 0 })
const o = this.toLayer(v, 0, 0)
const k = this.host != null ? v.transformTo(this.host).scale : 1
return ({ x: o.x, y: o.y, w: v.width * k, h: v.height * k })

const scr = this.screen()
if (this.host == null) return ({ x: Math.max(4, Math.min(scr.width - w - 4, x)), y: Math.max(4, Math.min(scr.height - h - 4, y)) })
const out = this.host.transformTo(scr)
const cs = [this.through(out, x, y), this.through(out, x + w, y), this.through(out, x, y + h), this.through(out, x + w, y + h)]
const minX = Math.min(...cs.map((c) => c.x))
const maxX = Math.max(...cs.map((c) => c.x))
const minY = Math.min(...cs.map((c) => c.y))
const maxY = Math.max(...cs.map((c) => c.y))
const dx = maxX > scr.width - 4 ? scr.width - 4 - maxX : 0
const dy = maxY > scr.height - 4 ? scr.height - 4 - maxY : 0
const sx = minX + dx < 4 ? 4 - minX : dx
const sy = minY + dy < 4 ? 4 - minY : dy
if (sx == 0 && sy == 0) return ({ x: x, y: y })
const back = scr.transformTo(this.host)
const p0 = this.through(back, cs[0].x, cs[0].y)
const p1 = this.through(back, cs[0].x + sx, cs[0].y + sy)
return ({ x: x + p1.x - p0.x, y: y + p1.y - p0.y })

// one Esc closes one overlay: the one on top when the key arrived
if (e.key != "Escape" || !classroot.shown) return
const s = classroot.strata()
if (s.handled === e || s.top() != classroot) return
s.handled = e
classroot.escape()

const out = []
const lines = html.replace(/<[^>]*>/g, "").split("\n")
for (let i = 0; i < lines.length; i++) {
    const m = /^\s*(class|schema)\s+([A-Z]\w*)/.exec(lines[i])
    if (m != null) out.push({ name: m[2], line: i })
    }
return out

const dir = this.root.viewedDir()
const base = this.root.mode
const q = String.fromCharCode(34)                     // the double quote, kept out of this body's regexes
const inc = new RegExp('<span class=' + q + 'k' + q + '>(include|script)<\\/span>\\s*\\[([\\s\\S]*?)\\]', 'g')
const str = new RegExp('<span class=' + q + 's' + q + '>' + q + '([^' + q + ']+)' + q + '<\\/span>', 'g')
const tag = new RegExp('(<span class=' + q + 'k' + q + '>class<\\/span> |schema )?<span class=' + q + 't' + q + '>([A-Z]\\w*)<\\/span>', 'g')
// the anchor's text is bare (no accent span inside): the accent would
// compose over the link color, and a link should read as a link —
// linkColor + linkUnderline on the HTMLText style it. The quote marks
// stay outside the anchor, in the string accent: the file is the link,
// its quoting is syntax.
const quote = '<span class=' + q + 's' + q + '>' + q + '</span>'
const out = html.replace(inc, (m, kw, body) =>
    '<span class=' + q + 'k' + q + '>' + kw + '</span> [' + body.replace(str, (m2, p) =>
        quote + '<a href=' + q + '#' + base + '/' + this.root.resolveRel(dir, p) + q + '>' + p + '</a>' + quote) + ']')
return out.replace(tag, (m, decl, t) => {
    if (decl) return m
    const at = this.root.declaredAt(t)
    if (at != "") return '<a href=' + q + '#' + at + q + '>' + t + '</a>'
    if (this.root.docsBase != "" && REFERENCE_CLASSES.includes(t)) return '<a href=' + q + this.root.docsBase + '#reference/' + t + q + '>' + t + '</a>'
    return m
    })

if (/^[a-z][a-z0-9+.-]*:\/\//i.test(dir)) return new URL(p, dir).href
const parts = (dir + p).split("/")
const stack = []
for (const s of parts) {
    if (s == "..") { if (stack.length == 0 || stack[stack.length - 1] == "..") stack.push(s); else stack.pop() }
    else if (s != "." && s != "") stack.push(s)
    }
return stack.join("/")
